import java.util.List;

/**
 * A class representing shared characteristics of animals.
 *
 * @version 2016.02.29 (2)
 */
public abstract class Animal
{
    // Whether the animal is alive or not.
    private boolean alive;
    // The animal's field.
    private Field field;
    // The animal's position in the field.
    private Location location;

    /**
     * Create a new animal at location in field.
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Animal(Field field, Location location)
    {
        alive = true;
        this.field = field;
        setLocation(location);
    }

    /**
     * Make this animal act - that is: make it do
     * whatever it wants/needs to do.
     * @param newAnimals A list to receive newly born animals.
     */
    abstract public void act(List<Animal> newAnimals);

    /**
     * Check whether the animal is alive or not.
     * @return true if the animal is still alive.
     */
    protected boolean isAlive()
    {
        return alive;
    }

    /**
     * Indicate that the animal is no longer alive.
     * It is removed from the field.
     */
    protected void setDead()
    {
        alive = false;
        if(location != null) {
            field.clear(location);
            location = null;
            field = null;
        }
    }

    /**
     * Return the animal's location.
     * @return The animal's location.
     */
    protected Location getLocation()
    {
        return location;
    }

    /**
     * Place the animal at the new location in the given field.
     * @param newLocation The animal's new location.
     */
    protected void setLocation(Location newLocation)
    {
        if(location != null) {
            field.clear(location);
        }
        location = newLocation;
        field.place(this, newLocation);
    }

    /**
     * Return the animal's field.
     * @return The animal's field.
     */
    protected Field getField()
    {
        return field;
    }
}

import java.util.Collections;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;
import java.util.Random;

/**
 * Represent a rectangular grid of field positions.
 * Each position is able to store a single actor.
 *
 * @version 18.02.22 (DD:MM:YY)
 */
public class Field
{
    // A random number generator for providing random locations:
    private static final Random rand = Randomizer.getRandom();
    // The depth and width of the field:
    private int depth, width;
    // Storage for the actors:
    private Object[][] field;
    private Field producerField;

    /**
     * Represent a field of the given dimensions.
     * 
     * @param depth The depth of the field.
     * @param width The width of the field.
     */
    public Field(int depth, int width)
    {
        this.depth = depth;
        this.width = width;

        field = new Object[depth][width];
    }

    /**
     * Empty the field.
     */
    public void clear()
    {
        for (int row = 0; row < depth; row++)
        {
            for (int col = 0; col < width; col++)
            {
                field[row][col] = null;
            }
        }
    }

    /**
     * Clear the given location.
     * 
     * @param location The location to clear.
     */
    public void clear(Location location)
    {
        field[location.getRow()][location.getCol()] = null;
    }

    /**
     * Place an actor at the given location.
     * If there is already an actor at the location it will
     * be lost.
     * 
     * @param actor The actor to be placed.
     * @param row   Row coordinate of the location.
     * @param col   Column coordinate of the location.
     */
    public void place(Object actor, int row, int col)
    {
        place(actor, new Location(row, col));
    }

    /**
     * Place an actor at the given location.
     * If there is already an actor at the location it will
     * be lost.
     * @param actor The actor to be placed.
     * @param location Where to place the actor.
     */
    public void place(Object actor, Location location)
    {
        field[location.getRow()][location.getCol()] = actor;
    }

    /**
     * Return the actor at the given location, if any.
     * 
     * @param location Where in the field.
     * @return The actor at the given location, or null if there is none.
     */
    public Object getObjectAt(Location location)
    {
        return getObjectAt(location.getRow(), location.getCol());
    }

    /**
     * Return the actor at the given location, if any.
     * 
     * @param row The desired row.
     * @param col The desired column.
     * @return The actor at the given location, or null if there is none.
     */
    public Object getObjectAt(int row, int col)
    {
        return field[row][col];
    }

    /**
     * Generate a random location that is adjacent to the
     * given location, or is the same location.
     * The returned location will be within the valid bounds
     * of the field.
     * @param location The location from which to generate an adjacency.
     * @return A valid location within the grid area.
     */
    public Location randomAdjacentLocation(Location location)
    {
        List<Location> adjacent = adjacentLocations(location);
        return adjacent.get(0);
    }

    /**
     * Get a shuffled list of the free adjacent locations.
     * 
     * @param searchLocation Get locations adjacent to this.
     * @return A list of free adjacent locations.
     */
    public List<Location> getFreeAdjacentLocations(Location searchLocation)
    {
        // The list of free locations to be returned:
        List<Location> free = new LinkedList<>();

        List<Location> adjacentLocations = adjacentLocations(searchLocation);

        for (Location location : adjacentLocations)
            if (getObjectAt(location) == null) free.add(location);

        return free;
    }

    /**
     * Try to find a free location that is adjacent to the
     * given location. If there is none, return null.
     * The returned location will be within the valid bounds
     * of the field.
     * 
     * @param searchLocation The location from which to generate an adjacency.
     * @return A valid location within the grid area.
     */
    public Location freeAdjacentLocation(Location searchLocation)
    {
        // Get a list of the free locations:
        List<Location> free = getFreeAdjacentLocations(searchLocation);

        // Return the first free location or null if there are none:
        if (free.size() > 0) return free.get(0);
        else                 return null;
    }

    /**
     * Return a shuffled list of locations adjacent to the given one.
     * The list will not include the location itself.
     * All locations will lie within the grid.
     * 
     * @param location The location from which to generate adjacencies.
     * @return A list of locations adjacent to that given.
     */
    public List<Location> adjacentLocations(Location location)
    {
        assert location != null : "Null location passed to adjacentLocations";

        // The list of locations to be returned:
        List<Location> locations = new LinkedList<>();

        if (location != null)
        {
            int row = location.getRow();
            int col = location.getCol();

            for (int roffset = -1; roffset <= 1; roffset++)
            {
                int nextRow = row + roffset;

                if (nextRow >= 0 && nextRow < depth)
                {
                    for (int coffset = -1; coffset <= 1; coffset++)
                    {
                        int nextCol = col + coffset;

                        // Exclude invalid locations and the original location:
                        if (nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0))
                        {
                            locations.add(new Location(nextRow, nextCol));
                        }
                    }
                }
            }

            // Shuffle the list. Several other methods rely on the list
            // being in a random order:
            Collections.shuffle(locations, rand);
        }
        return locations;
    }

    /**
     * @return The depth of the field.
     */
    public int getDepth() { return depth; }

    /**
     * @return The width of the field.
     */
    public int getWidth() { return width; }
    public Field createProducerField()
    {
         producerField = new Field(width,depth);
         return producerField;
    }
    public Field getProducerField()
    {
        return producerField;
    }
}

import java.util.Random;
import java.util.List;

/**
 * An actor in our simulation that performs a set of actions.
 *
 * @version 18.02.22 (DD:MM:YY)
 */
public abstract class Actor
{
    // Whether the actor is alive or not:
    private boolean isAlive;
    // The actor's field:
    private Field field;
    // The actor's position in the field:
    private Location location;
    // The worth of the actor if consumed:
    protected int consumptionWorth;
    // The gender of the actor:
    protected Gender gender;
    // The probability of this actor breeding:
    private double breedingProbability;
    // The max number of births this actor can have in one step:
    private int maxBirthsAtOnce;
    // A shared random number generator controlling breeding:
    protected static final Random rand = Randomizer.getRandom();
    // The maximum amount of food an actor can eat:
    protected int maxSustenanceLevel;
    // The maximum age the actor can have:
    protected int maxAge;
    // The current age of the actor:
    protected int currentAge;


    /**
     * Create a new actor at a location in the field.
     * 
     * @param field            The field currently occupied.
     * @param location         The location within the field.
     * @param consumptionWorth The worth of the actor if consumed.
     */
    public Actor(Field field, Location location, int consumptionWorth,
                 double breedingProbability, int maxBirthsAtOnce,int maxSustenanceLevel,int maxAge)
    {
        isAlive = true;
        this.field = field;
        setLocation(location);
        this.consumptionWorth = consumptionWorth;
        this.breedingProbability = breedingProbability;
        this.maxBirthsAtOnce = maxBirthsAtOnce;
        gender = Gender.getRandom();
        this.maxSustenanceLevel = maxSustenanceLevel;
        this.maxAge = maxAge;
    }

    /**
     * Make this actor act - that is: make it do
     * whatever it wants/needs to do.
     * 
     * @param newActors A list to receive newly born actors.
     */
    abstract public void act(List<Actor> newActors);

    /**
     * @return The probability of this actor breeding.
     */
    protected double getBreedingProbability() { return breedingProbability; }

    /**
     * @return The max number of births this actor can have in one step.
     */
    protected int getMaxBirthsAtOnce() { return maxBirthsAtOnce; }

    /**
     * @return The gender of this actor.
     */
    public Gender getGender() { return gender; }

    /**
     * @return The worth of this actor if consumed.
     */
    public int getConsumptionWorth() { return consumptionWorth; }

    /**
     * @return True if the actor is still alive.
     */
    public boolean getIsAlive() { return isAlive; }

    /**
     * Indicate that the actor is no longer alive.
     * It is removed from the field.
     */
    protected void setDead()
    {
        isAlive = false;
        if (location != null)
        {
            field.clear(location);
            location = null;
            field = null;
        }
    }

    /**
     * @return The actor's location.
     */
    protected Location getLocation() { return location; }

    /**
     * Place the actor at the new location in the given field.
     * 
     * @param newLocation The actor's new location.
     */
    protected void setLocation(Location newLocation)
    {
        if (location != null) field.clear(location);

        location = newLocation;
        field.place(this, newLocation);
    }

    /**
     * @return The actor's field.
     */
    protected Field getField() { return field; }

    /**
     * Increase the age.
     * This could result in the actor's death.
     */
    protected void incrementAge()
    {
        currentAge++;

        if (currentAge > maxAge) {

            setDead();
        }

    }
    /**
     * Returns true if the actor can become a carcass and false if it can't.
     * return if the actor can become a carcass.
     */
    protected abstract boolean becomeCarcass();
}

 import java.util.Random;
import java.util.List;
import java.util.ArrayList;
import java.util.Iterator;
import java.awt.Color;
import javafx.application.Application;

/**
 * A simple predator-prey simulator, based on a rectangular field.
 *
 * @version 18.02.22 (DD:MM:YY)
 */
public class Simulator
{
    // Constants representing configuration information for the simulation:
    //   The default width for the grid:
    private static final int DEFAULT_WIDTH = 120;
    //   The default height for the grid:
    private static final int DEFAULT_DEPTH = 160;

    // Constants representing the creation probabilities for the actors:
    //   Primary consumers:
    private static final double GRASSHOPPER_CREATION_PROBABILITY   = 0.15;
    private static final double HARVESTER_ANT_CREATION_PROBABILITY = 0.25;
    private static final double TERMITE_CREATION_PROBABILITY       = 0.21;
    private static final double IMPALA_CREATION_PROBABILITY        = 0.15;
    //   Secondary consumers:
    private static final double PANGOLIN_CREATION_PROBABILITY      = 0.125;
    private static final double AARDVARK_CREATION_PROBABILITY      = 0.12;
    private static final double MONGOOSE_CREATION_PROBABILITY      = 0.12;
    //   Producers:
    private static final double STAR_GRASS_CREATION_PROBABILITY    = 0.05;
    private static final double RED_OAT_GRASS_CREATION_PROBABILITY = 0.04;
    private static final double ACACIA_CREATION_PROBABILITY        = 0.04;

    // Constants representing the color of each actor in the simulation view:
    //   Primary consumers:
    private static final Color GRASSHOPPER_COLOR   = new Color(188, 248, 236);
    private static final Color HARVESTER_ANT_COLOR = new Color(4, 139, 168);
    private static final Color TERMITE_COLOR       = new Color(22, 219, 147);
    private static final Color IMPALA_COLOR        = new Color(239, 234, 90);
    //   Secondary consumers:
    private static final Color PANGOLIN_COLOR      = new Color(242, 158, 76);
    private static final Color AARDVARK_COLOR      = new Color(204, 183, 174);
    private static final Color MONGOOSE_COLOR      = new Color(65, 69, 53);
    //   Producers:
    private static final Color STAR_GRASS_COLOR    = new Color(125, 97, 103);
    private static final Color RED_OAT_GRASS_COLOR = new Color(164, 3, 111);
    private static final Color ACACIA_COLOR        = new Color(187, 214, 134);
    // Carcasses of consumers
    private static final Color CARCASS_COLOR       = new Color(202,0,0);

    // The number of steps in a day:
    public static final int NUMBER_OF_STEPS_PER_DAY = 25;

    // List of actors in the field:
    private List<Actor> actors;
    // The current state of the field:
    private static Field field;
    // The current step of the simulation.
    private static int step = 0;
    // A graphical view of the simulation:
    private static SimulatorView view;
    // A Boolean indicating whether or not to reset the StatisticsView:
    public static boolean resetStatisticsView = false;

    /**
     * Construct a simulation field with default size.
     */
    public Simulator()
    {
        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
    }

    /**
     * Create a simulation field with the given size.
     * 
     * @param depth Depth of the field. Must be greater than zero.
     * @param width Width of the field. Must be greater than zero.
     */
    public Simulator(int depth, int width)
    {
        boolean isSizeImpossible = depth <= 0 || depth <= 0;

        if (isSizeImpossible)
        {
            System.out.println("The dimensions must be greater than zero.");
            System.out.println("Using default values.");

            depth = DEFAULT_DEPTH;
            width = DEFAULT_WIDTH;
        }

        actors = new ArrayList<>();
        field = new Field(depth, width);

        // Set the initial weather:
        WeatherSystem.changeToNextDay();

        // Create a view of the state of each location in the field:
        view = new SimulatorView(this,depth, width);

        view.setColor(Grasshopper.class, GRASSHOPPER_COLOR);
        view.setColor(HarvesterAnt.class, HARVESTER_ANT_COLOR);
        view.setColor(Termite.class, TERMITE_COLOR);
        view.setColor(Impala.class, IMPALA_COLOR);
        view.setColor(Pangolin.class, PANGOLIN_COLOR);
        view.setColor(Aardvark.class, AARDVARK_COLOR);
        view.setColor(Mongoose.class, MONGOOSE_COLOR);
        view.setColor(StarGrass.class, STAR_GRASS_COLOR);
        view.setColor(RedOatGrass.class, RED_OAT_GRASS_COLOR);
        view.setColor(Acacia.class, ACACIA_COLOR);
        view.setColor(Carcass.class, CARCASS_COLOR);

        // Show the statistics window:
        new Thread(() -> {
            Application.launch(StatisticsView.class);
        }).start();

        // Setup a valid starting point:
        reset();
    }

    /**
     * @return The current step in the simulation.
     */
    public static int getCurrentStep() { return step; }

    /**
     * @return The current field in the simulation.
     */
    public static Field getCurrentField() { return field; }

    /**
     * Run the simulation from its current state for a reasonably long period,
     * (4000 steps).
     */
    public void runLongSimulation()
    {
        simulate(4000);
    }

    /**
     * Run the simulation from its current state for the given number of steps.
     * Stop before the given number of steps if it ceases to be viable.
     * 
     * @param numSteps The number of steps to run for.
     */
    public void simulate(int numSteps)
    {
        for (int step = 1; step <= numSteps && view.isViable(field); step++)
        {
            simulateOneStep();
            //delay(60);   // uncomment this to run more slowly
        }
    }

    /**
     * Run the simulation from its current state for a single step.
     * Iterate over the whole field updating the state of each
     * fox and rabbit.
     */
    public void simulateOneStep()
    {
        step++;

        // Update the weather:
        if (TimeSystem.hasDayChanged())
        {
            WeatherSystem.changeToNextDay();

        }

        // Provide space for newborn actors:
        List<Actor> newActors = new ArrayList<>();

        // Let all rabbits act:
        for (Iterator<Actor> it = actors.iterator(); it.hasNext(); )
        {
            Actor actor = it.next();

            actor.act(newActors);

            if(!actor.getIsAlive()) it.remove();
        }

        // Add the newly born foxes and rabbits to the main lists:
        actors.addAll(newActors);

        view.showStatus(step, field);
    }

    /**
     * Reset the simulation to a starting position.
     */
    public void reset()
    {
        step = 0;
        actors.clear();
        populate();

        // Show the starting state in the view:
        view.showStatus(step, field);

        // Toggle boolean to show StatisticsView should be reset:
        resetStatisticsView = true;
    }

    /**
     * Randomly populate the field with foxes and rabbits.
     */
    private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();

        for (int row = 0; row < field.getDepth(); row++)
        {
            for (int col = 0; col < field.getWidth(); col++)
            {
                Location location = new Location(row, col);
                Actor actor;

                // Refactor this?
                if (rand.nextDouble() <= GRASSHOPPER_CREATION_PROBABILITY)
                    actors.add(new Grasshopper(true, field, location));
                else if (rand.nextDouble() <= HARVESTER_ANT_CREATION_PROBABILITY)
                    actors.add(new HarvesterAnt(true, field, location));
                else if (rand.nextDouble() <= TERMITE_CREATION_PROBABILITY)
                    actors.add(new Termite(true, field, location));
                else if (rand.nextDouble() <= IMPALA_CREATION_PROBABILITY)
                    actors.add(new Impala(true, field, location));
                else if (rand.nextDouble() <= PANGOLIN_CREATION_PROBABILITY)
                    actors.add(new Pangolin(true, field, location));
                else if (rand.nextDouble() <= AARDVARK_CREATION_PROBABILITY)
                    actors.add(new Aardvark(true, field, location));
                else if (rand.nextDouble() <= MONGOOSE_CREATION_PROBABILITY)
                    actors.add(new Mongoose(true, field, location));
                else if (rand.nextDouble() <= STAR_GRASS_CREATION_PROBABILITY)
                    actors.add(new StarGrass(field, location));
                else if (rand.nextDouble() <= RED_OAT_GRASS_CREATION_PROBABILITY)
                    actors.add(new RedOatGrass(field, location));
                else if (rand.nextDouble() <= ACACIA_CREATION_PROBABILITY)
                    actors.add(new Acacia(field, location));

                // Else leave the location empty.
            }
        }
    }

    /**
     * Pause for a given time.
     * 
     * @param millisec The time to pause for, in milliseconds
     */
    private void delay(int millisec)
    {
        try
        {
            Thread.sleep(millisec);

            Thread.sleep(millisec);
        }
        catch (InterruptedException ie)
        {
            // Wake up.
        }
    }
}

import java.util.List;
import java.util.Random;
import java.util.ArrayList;
import java.util.Iterator;

/**
 * A class representing shared characteristics of consumers.
 *
 * @version 18.02.22 (DD:MM:YY)
 */
public abstract class Consumer extends Actor
{
    // Properties shared between all consumers:
    private static final int STARTING_SUSTENANCE_LEVEL = 20;
    private static final double NEW_DISEASE = 0.0005;
    private static final double NIGHT_PREY_MISS_PROBABILITY = 0.5;
    private static Random rand = Randomizer.getRandom();

    // Properties unique to this consumer:
    private int breedingAge;
    private int sustenanceLevel;
    private int maxSustenanceLevel;
    private ArrayList<Class> prey;
    private Disease disease;
    private boolean ifCarcass;
    private Carcass newCarcass;
    private boolean canEatCarcass;
    private boolean primaryConsumer;

    /**
     * Create a new consumer at a location in the field.
     * 
     * @param field               The field currently occupied.
     * @param location            The location within the field.
     * @param consumptionWorth    The worth of the consumer if consumed.
     * @param breedingProbability The liklihood of the consumer breeding.
     * @param maxBirthsAtOnce     The max number of births for the consumer.
     * @param maxAge              The age to which this consumer can live.
     * @param breedingAge         The age at which this consumer can start to breed.
     */
    public Consumer(Field field, Location location, ArrayList<Class> prey, int consumptionWorth,
                    double breedingProbability, int maxBirthsAtOnce, int maxAge, int breedingAge,int maxSustenanceLevel,boolean canEatCarcass,boolean primaryConsumer)
    {
        super(field, location, consumptionWorth, breedingProbability, maxBirthsAtOnce,maxSustenanceLevel,maxAge);
        this.canEatCarcass = canEatCarcass;
        this.prey = prey;
        this.maxAge = maxAge;
        this.breedingAge = breedingAge;
        this.primaryConsumer = primaryConsumer;
        sustenanceLevel = 30;
    }

    /**
     * Make this consumer act - that is: make it do
     * whatever it wants/needs to do.
     * 
     * @param newConsumers A list to receive newly born consumers.
     */
    public void act(List<Actor> newConsumers)
    {   
        incrementAge();
        incrementHunger();
        if (getIsAlive())
        {
            giveBirth(newConsumers);
            boolean wasPossibleToMove = huntForFood();
            if(ifCarcass)
            {
                newConsumers.add(newCarcass);
                ifCarcass = false;
                newCarcass = null;
            }
            if(hasDisease())
            {                                                                                   
                diseaseEffect();
            }
            if (!wasPossibleToMove)
            {
                setDead();
            }
        }
    }
    /**
     * Returns true if this consumer is diseased else return false.
     * @return boolean
     */
    private boolean hasDisease()
    {
        return this.disease != null;
    }
    /**
     * Returns a new Disease.
     * @return diseae
     */
    private Disease giveDisease()
    {
        return new Disease();
    }
    /**
     * If the animal is diseased then evolve the disease.
     */
    private void diseaseEffect()
    {
        if(hasDisease())
        {
            disease.decrementStepsBeforeDeath();
            spreadDisease();
            checkForFatalDisease();
            incrementHunger();
        }
    }
    /**
     * Check if the disease is fatal to the animal.
     */
    private void checkForFatalDisease()
    {
        if(hasDisease() && disease.diseaseFinished())
        {   
            if(disease.isFatal())
            {
                setDead();
            }
            disease = null;
        }
    }
    /**
     * Spread the disease to different animals of the same species.
     */
    private void spreadDisease()
    {
            Field field = getField();
            List<Location> adjacent = field.adjacentLocations(getLocation());
            Iterator<Location> it = adjacent.iterator();
            while(it.hasNext())

            {
                Location loc = it.next();
                Object animal = field.getObjectAt(loc);
                Actor consumer = (Actor) animal;
                if(consumer != null && consumer.getClass() == this.getClass() && this.hasDisease())
                {
                    ((Consumer) consumer).disease = giveDisease();
                }
            }
    }
    /**
     * Hunt for food by moving toward it.
     */
    private boolean huntForFood()
    {
        // Move towards a source of food if found:
        Location newLocation = findFood();

        if (newLocation == null)
        { 
            // No food found - try to move to a free location:
            newLocation = getField().freeAdjacentLocation(getLocation());
        }

        // See if it was possible to move.
        if (newLocation != null) setLocation(newLocation);

        return newLocation != null;
    }

    /**
     * Set the starting age of the consumer, dependent on whether a random
     * age has been selected.
     * 
     * @param randomAge If true, the age is random, otherwise it's 0.
     */
    protected void setStartingAge(boolean randomAge)
    {
        if (randomAge) currentAge = rand.nextInt(maxAge) ;
        else           currentAge = 0;
    }


    /**
     * Check whether or not this consumer is to give birth at this step.
     * New births will be made into free adjacent locations.
     * 
     * @param newConsumers A list to return newly born consumers.
     */
    private void giveBirth(List<Actor> newConsumers)
