    /**
     * @return True if there is a valid mate in an adjacent location for the consumer.
     */
    private boolean checkForValidMate()
    {   
        Field field = getField();

        for (Location location : field.adjacentLocations(getLocation()))
        {
            Object object = field.getObjectAt(location);

            if (object instanceof Consumer                 // Is there a consumer in that location?
                && object.getClass() == this.getClass()    // Is the consumer of the same type as this one?
                && ((Consumer) object).canBreed()          // Can that consumer breed?
                && ((Actor) object).getGender() != gender) // Is that consumer of the opposite sex?
            {
                return true; // We have found a valid mate.
            }
        }

        return false; // We didn't manage to find a valid mate.
    }

    /**
     * Generate a number representing the number of births,
     * if it can breed.
     * 
     * @return The number of births (may be zero).
     */
    private int breed()
    {
        int births = 0;

        boolean willBreed = rand.nextDouble()
                            <= getBreedingProbability();

        if (canBreed() && willBreed)
            births = rand.nextInt(getMaxBirthsAtOnce()) + 1;

        return births;
    }

    /**
     * A consumer can breed if it has reached the breeding age.
     * 
     * @return True if the consumer can breed, false otherwise.
     */
    private boolean canBreed() { return currentAge >= breedingAge; }

    /**
     * Make this consumer more hungry. This could result in the consumer's death.
     */
    private void incrementHunger()
    {
        sustenanceLevel--;
        if (sustenanceLevel <= 0) setDead();
    }

    /**
     * Look for prey adjacent to the current location.
     * Only the first live prey is eaten.
     * 
     * @return Where food was found, or null if it wasn't.
     */
    private Location findFood()
    {
        // Get adjacent locations:
        Field field;
        field = getField();
        List<Location> adjacentLocations = field.adjacentLocations(getLocation());

        Iterator<Location> it = adjacentLocations.iterator();

        while (it.hasNext())
        {
            Location where = it.next();
            Object object = field.getObjectAt(where);

            for (Class preyClass : prey)
            {   
                if (preyClass.isInstance(object))
                {   
                    Actor actor = (Actor) object;

                    if (actor.getIsAlive())
                    {   
                        // If it's night, there is a probability of missing the prey:
                        if (TimeSystem.isNightTime())
                        {   
                            if (rand.nextDouble() <= 1.0 - NIGHT_PREY_MISS_PROBABILITY)
                            {   

                                return eat(actor);
                            }
                        }
                        else
                        {

                            return eat(actor);
                        }
                    }
                }
            }
            if(Carcass.class.isInstance(object))
            {   
                if(canEatCarcass)
                {
                    Carcass carcass = (Carcass) object;
                    if(carcass.isDiseased())
                    {
                        this.disease = giveDisease();
                    }
                    sustenanceLevel += carcass.getConsumptionWorth();
                    carcass.setDead();
                    return where;
                }
            }
        }

        return null;
    }
    protected boolean becomeCarcass()
    {
        return true;
    }
    /**
     * Makes the animal eat the food and generate a carcass if necessary.
     * @param actor The actor who is to be eaten.
     */
    private Location eat(Actor actor)
    {   
        Location location = actor.getLocation();
        int actorConsumptionWorth = actor.getConsumptionWorth();
        if(actor.becomeCarcass())
        {   
            actor.setDead();
            if((sustenanceLevel + actorConsumptionWorth) > maxSustenanceLevel)
            {   
                int foodLeft = (sustenanceLevel + consumptionWorth) - maxSustenanceLevel;
                sustenanceLevel = this.maxSustenanceLevel;
                Carcass carcass = new Carcass(getField(),location,foodLeft);
                newCarcass = carcass;
                ifCarcass = true;
                return getLocation();
            }  
        }
        if(sustenanceLevel + actorConsumptionWorth <= maxSustenanceLevel)
        {
            sustenanceLevel += actorConsumptionWorth;
            return location;
        }
        return null;
    }
}

import java.util.Random;

/**
 * Provide control over the randomization of the simulation. By using the shared, fixed-seed 
 * randomizer, repeated runs will perform exactly the same (which helps with testing). Set 
 * 'useShared' to false to get different random behaviour every time.
 *
 * @version 18.02.22 (DD:MM:YY)
 */
public class Randomizer
{
    // The default seed for control of randomization:
    private static final int SEED = 10001;
    // A shared Random object, if required:
    private static final Random rand = new Random(SEED);
    // Determine whether a shared random generator is to be provided:
    private static final boolean useShared = true;

    /**
     * Provide a random generator.
     * 
     * @return A random object.
     */
    public static Random getRandom()
    {
        if (useShared) return rand;
        else           return new Random();
    }

    /**
     * Reset the randomization.
     * This will have no effect if randomization is not through
     * a shared Random generator.
     */
    public static void reset()
    {
        if (useShared) rand.setSeed(SEED);
    }
    public static void setSeed(int seed)
    {
        rand.setSeed(seed);
    }
}

import java.util.Random;
import java.util.List;
/**
 * A simple model of a carcass.
 *
 * @version 27.02.22 (DD:MM:YY)
 */
class Carcass extends Actor
{   
    //the carcass may be diseased if its left for too long:
    private boolean diseased;
    // Number of steps before the corpse becomes infected:
    private int STEPS_BEFORE_INFECTION;
    /**
     * Create a new carcass at a location in the field.
     * 
     * @param field            The field currently occupied.
     * @param location         The location within the field.
     * @param consumptionWorth The worth of the actor if consumed.
     */
    Carcass(Field field,Location loc,int consumptionWorth)
    {   
        super(field,loc,consumptionWorth,0,0,0,1);
        STEPS_BEFORE_INFECTION = rand.nextInt(15);
    }
    /**
     * Decrements the number of steps for the carcass to be infected every step in the simulator.
     */
    private void decrementStepsBeforeInfection()
    {
        STEPS_BEFORE_INFECTION--;
    }
    /**
     * Sets the Carcass to be diseased(any consumer to eat it will be diseased as well)
     */
    private void makeDiseased()
    {
        if(STEPS_BEFORE_INFECTION == 0)
        {
            diseased = true;
        }
    }
    /**
     * Make this carcass act - that is: make it do
     * whatever it needs to do.
     * 
     * @param newCarcasses A list to receive newly born consumers.
     */
    public void act(List<Actor> newCarcasses)
    {
        decrementStepsBeforeInfection();
        makeDiseased();
    }
    /**
     * Returns true if the carcass is diseased and false if it isn't.
     * return if the carcass is diseased
     */
    public boolean isDiseased()
    {
        return this.diseased;
    }
    /**
     * Returns true if the actor can become a carcass and false if it can't.
     * return if the actor can become a carcass.
     */
    protected boolean becomeCarcass()
    {
        return false;
    }
}

